'use strict';
const params=new URLSearchParams(location.search), root=document.documentElement;
const state={view:params.get('view')||'overview',tab:params.get('tab')||'observed',section:params.get('section')||'style',theme:params.get('theme')||'dark',scope:'work',memory:true,plugin:params.get('plugin')!=='off',motion:true,chat:true,name:'Bublina',position:'Produktová designérka',department:'Produkt',open:'demo-style-1',editor:null,origin:'overview',eraseId:null};
if(params.has('font')){root.style.fontSize=(16*Number(params.get('font')))+'px';if(Number(params.get('font'))>1.3)root.classList.add('large-text')}
const icons={back:'<path d="m14 6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',settings:'<path d="M4 7h5m5 0h6M4 17h9m5 0h2"/><circle cx="11.5" cy="7" r="2.5"/><circle cx="15.5" cy="17" r="2.5"/>',work:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V4h8v3M3 12q9 6 18 0M10 14h4"/>',projects:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/><path d="M6 10v7h8"/>',tools:'<path d="M14 6a5 5 0 0 0-6 6L3 17a3 3 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-3 3-4-4 3-3Z"/>',people:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M16 4a4 4 0 0 1 0 8M18 15a5 5 0 0 1 4 5"/>',style:'<path d="M21 15a3 3 0 0 1-3 3H7l-5 4V5a3 3 0 0 1 3-3h13a3 3 0 0 1 3 3Z"/>',rhythm:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6h4"/>',edit:'<path d="m15 4 5 5M4 16l12-12a3 3 0 0 1 4 4L8 20l-5 1Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',check:'<path d="m5 12 4 4L19 6"/>',wifi:'<path d="M2 8q10-8 20 0M5 12q7-6 14 0M9 16q3-3 6 0M12 20h.01"/>',battery:'<rect x="2" y="5" width="17" height="14" rx="2"/><path d="M22 10v4"/>',book:'<path d="M12 5q-4-3-10-1v16q6-2 10 1 4-3 10-1V4q-6-2-10 1v16"/>'};
const svg=(name,cl='')=>`<svg class="${cl}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.chevron}</svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sectionList=[['work','Práce'],['projects','Projekty'],['tools','Nástroje'],['people','Lidé'],['style','Styl'],['rhythm','Rytmus']];
let observations=[{id:'demo-style-1',section:'style',personal:false,content:'Preferuješ stručné shrnutí a další kroky.',source:{type:'chat',at:'24. 10.',removed:false},seenAt:'včera',revision:1,trust:'model_inference'},{id:'demo-style-2',section:'style',personal:false,content:'Vyhovují ti jasné seznamy úkolů.',source:{type:'chat',at:'22. 10.',removed:true},seenAt:'22. 10.',revision:1,trust:'model_inference'},{id:'demo-work-1',section:'work',personal:false,content:'Připravuješ návrhy nových služeb.',source:{type:'meeting',at:'23. 10.',removed:false},seenAt:'23. 10.',revision:1,trust:'model_inference'},{id:'demo-tools-1',section:'tools',personal:false,content:'Při návrhu pracuješ ve Figmě.',source:{type:'chat',at:'21. 10.',removed:false},seenAt:'21. 10.',revision:1,trust:'model_inference'}];
let saved=[{id:'demo-saved-1',content:'Odpovídej mi česky.',trust:'user_assertion',source:'user_note'},{id:'demo-saved-2',content:'Pracovní týden začíná v pondělí.',trust:'verified_result',source:'verified_operation'}];
let history=[];
function focusKey(el=document.activeElement){return el?.id|| (el?.dataset?.action?'action:'+el.dataset.action:'')}
function restoreFocus(key){const el=key?.startsWith('action:')?document.querySelector('[data-action="'+CSS.escape(key.slice(7))+'"]'):document.getElementById(key);el?.focus({preventScroll:true})}
function setTheme(theme){state.theme=theme;root.classList.toggle('light',theme==='light'||(theme==='system'&&matchMedia('(prefers-color-scheme: light)').matches))}
setTheme(state.theme);
const button=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function header(title,appearance=false){return `<header class="header">${button(svg('back'),'back','icon-button back','aria-label="Zpět"')}<h1>${title}</h1>${appearance?button(svg('settings'),'appearance','icon-button','aria-label="Vzhled a prostředí" id="appearance-opener"'):''}</header>`}
function pet(compact=false,appearance=false){return `<div class="pet-stage ${compact?'compact':''} ${appearance?'appearance-stage':''}"><img class="pet" src="assets/pet-${root.classList.contains('light')?'light':'dark'}.png" alt="" width="480" height="480"><p class="pet-name">${escape(state.name)}</p></div>`}
function tabs(){return `<nav class="tabs" aria-label="Informace o tobě">${[['observed','Poznatky'],['saved','Uložené'],['about','O tobě']].map(([id,label])=>button(label,'tab:'+id,'tab '+(state.tab===id?'selected':''),`aria-current="${state.tab===id?'page':'false'}" id="tab-${id}"`)).join('')}</nav>`}
function toggle(label,id,on,cls='',disabled=false){return button(`<span>${label}</span><i class="switch" aria-hidden="true"></i>`,'toggle:'+id,'switch-button '+cls,`role="switch" aria-checked="${on}" ${disabled?'disabled':''}`)}
function scope(){return `<div class="scope"><select aria-label="Oblast poznatků" id="scope"><option value="work" ${state.scope==='work'?'selected':''}>Pracovní</option><option value="personal" ${state.scope==='personal'?'selected':''}>Osobní</option></select>${toggle('Paměť','memory',state.memory&&state.plugin,'',!state.plugin)}</div>${!state.plugin?'<p class="note-state">Paměť nedostupná</p>':''}`}
function overview(){return `${scope()}${pet()}<div class="sections" aria-label="Oblasti poznatků">${sectionList.map(([id,label])=>button(`${svg(id)}<span>${label}</span>${svg('chevron','chevron')}`,'section:'+id,'section-button',`id="section-${id}" aria-expanded="false"`)).join('')}</div>`}
function sourceText(r){return r.source.removed?'Zdroj odebrán':r.source.type==='chat'?'Z chatu':'Ze schůzky'}
function memoryRow(r){const open=state.open===r.id;return `<article class="memory-row" id="${r.id}">${button(`<span>${escape(r.content)}</span>${open?'':svg('chevron')}`,'expand:'+r.id,'memory-toggle',`aria-expanded="${open}" aria-controls="detail-${r.id}"`)}${open?`<div id="detail-${r.id}"><div class="source-row">${r.source.removed?`<span>${sourceText(r)}</span>`:button(sourceText(r),'source:'+r.id,'source-button')}<span>${r.source.at}</span></div><p class="meta">Naposledy zaznamenáno ${r.seenAt}</p><div class="actions">${state.memory&&state.plugin?button(svg('edit')+'Opravit','correct:'+r.id,'outline'):''}${button(svg('trash')+'Smazat','delete:'+r.id,'outline')}</div></div>`:''}</article>`}
function detail(){const title=sectionList.find(([id])=>id===state.section)[1],records=observations.filter(r=>r.section===state.section&&r.personal===(state.scope==='personal'));return `${pet(true)}${button(svg('back')+'Všechny oblasti','all','return')}<h2 id="detail-heading" class="detail-heading" tabindex="-1">${title}</h2>${!state.plugin?'<p class="note-state">Paměť nedostupná</p>':''}${records.length?records.map(memoryRow).join(''):'<p class="note-state">Zatím žádné poznatky.</p>'}`}
function savedView(){return `${pet(true)}<div class="heading-row"><h2 id="detail-heading" tabindex="-1">Uložené</h2>${button(svg('more'),'erase-menu','icon-button','aria-label="Správa paměti"')}</div>${saved.length?saved.map(r=>`<article class="memory-row" id="${r.id}" tabindex="-1"><p class="memory-statement">${escape(r.content)}</p><p class="meta">${r.trust==='user_assertion'?'Přidáno tebou':r.trust==='verified_result'?'Ze služby':'Z chatu'}</p><div class="actions">${state.memory&&state.plugin?button('Upravit','correct:'+r.id,'outline'):''}${button('Smazat','delete:'+r.id,'outline')}</div></article>`).join(''):'<p class="note-state">Zatím nic uloženého.</p>'}`}
function setting(label,value,action){return button(`<span>${label}</span><span class="value">${escape(value)}${svg('chevron')}</span>`,action,'settings-row')}
function aboutView(){return `${pet(true)}<h2 id="detail-heading" tabindex="-1">O tobě</h2>${setting('Pozice',state.position,'position')}${setting('Oddělení',state.department,'position')}`}
function appearance(){return `${header('Vzhled a prostředí')}<main class="content">${pet(false,true)}<section class="group"><h3 class="group-title">Vzhled</h3>${setting('Jméno',state.name,'name')}${toggle('Pohyb peta','motion',state.motion,'settings-row')}${toggle('Zobrazit v chatu','chat',state.chat,'settings-row')}</section><section class="group"><h3 class="group-title">Prostředí</h3>${setting('Motiv',{dark:'Tmavý',light:'Světlý',system:'Systém'}[state.theme],'theme')}${setting('Počasí','Vypnuto','weather')}</section></main>`}
function editor(){let label,title,value;const e=state.editor;if(e.type==='name'){title='Jméno';label='Jméno';value=state.name}else if(e.type==='position'){title='O tobě';label='Pozice';value=state.position}else{title='Opravit';label='Text';value=e.content}return `${header(title)}<main class="content editor"><form id="edit-form"><label class="field">${label}${e.type==='memory'?`<textarea id="edit-value" maxlength="4000">${escape(value)}</textarea>`:`<input id="edit-value" maxlength="100" value="${escape(value)}">`}</label>${e.type==='position'?`<label class="field">Oddělení<input id="department" maxlength="100" value="${escape(state.department)}"></label>`:''}<div class="actions">${button('Zrušit','back','outline','type="button"')}<button class="primary" type="submit">Uložit změny</button></div></form></main>`}
function theme(){return `${header('Motiv')}<main class="content editor" role="radiogroup" aria-label="Motiv">${[['system','Systém'],['light','Světlý'],['dark','Tmavý']].map(([id,label])=>button(`<span>${label}</span><i class="radio" aria-hidden="true"></i>`,'theme:'+id,'choice',`role="radio" aria-checked="${state.theme===id}" tabindex="${state.theme===id?0:-1}"`)).join('')}</main>`}
function weather(){return `${header('Počasí')}<main class="content editor"><div class="choice"><span>Vypnuto</span>${svg('check')}</div>${button('<span>Město</span>'+svg('chevron'),'weather-context','choice')}${button('<span>Použít polohu telefonu</span>'+svg('chevron'),'weather-context','choice')}</main>`}
function library(){return `${header('Knihovna')}<main class="content"><div class="brand" aria-hidden="true" style="margin:28px 0"></div>${button('<i class="pet-icon" aria-hidden="true"></i><span>Ty a Niaro</span>'+svg('chevron'),'profile','plain-row','id="profile-entry"')}${button(svg('settings')+'<span>Nastavení</span>'+svg('chevron'),'appearance','plain-row')}</main>`}
function render(focus){let body;if(state.view==='appearance')body=appearance();else if(state.view==='editor')body=editor();else if(state.view==='theme')body=theme();else if(state.view==='weather')body=weather();else if(state.view==='library')body=library();else body=header('Ty a Niaro',true)+tabs()+`<main class="content">${state.tab==='about'?aboutView():state.tab==='saved'?savedView():state.view==='detail'?detail():overview()}</main>`;document.querySelector('#app').innerHTML=`<div class="shell"><div class="statusbar" aria-hidden="true"><span>9:41</span><span class="statusmarks">${svg('wifi')}${svg('battery')}</span></div>${body}<div class="home-indicator" aria-hidden="true"></div></div>`;if(focus)requestAnimationFrame(()=>restoreFocus(focus));bind()}
function go(view,focus){history.push({view:state.view,tab:state.tab,section:state.section,scroll:scrollY,focus:focusKey()});state.view=view;render(focus);window.scrollTo(0,0)}
function back(){const prev=history.pop();if(prev){Object.assign(state,{view:prev.view,tab:prev.tab,section:prev.section});render(prev.focus);requestAnimationFrame(()=>window.scrollTo(0,prev.scroll))}else if(state.view==='detail'){state.view='overview';render('section-'+state.section)}else{state.view='library';state.tab='observed';render('profile-entry');window.scrollTo(0,0)}}
function announce(t){document.getElementById('announcer').textContent=t}
function modal(title,copy,buttons,onClose){const opener=document.activeElement;const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','modal-title');dialog.innerHTML=`<h2 id="modal-title">${title}</h2>${copy?`<p>${copy}</p>`:''}<div class="actions">${buttons.map(b=>`<button class="${b.danger?'primary':'outline'}" data-modal="${b.id}">${b.label}</button>`).join('')}</div>`;document.body.append(dialog);dialog.addEventListener('close',()=>{dialog.remove();if(opener?.isConnected)opener.focus();onClose?.()});dialog.addEventListener('click',e=>{const b=e.target.closest('[data-modal]');if(b){dialog.close();if(b.dataset.modal==='confirm')confirmErase();if(b.dataset.modal==='erase-all')askErase('all')}});dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const stops=[...dialog.querySelectorAll('button:not([disabled]),input,textarea,select,a[href]')];const first=stops[0],last=stops.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});dialog.showModal()}
function askErase(id){state.eraseId=id;modal(id==='all'?'Smazat všechny vzpomínky?':'Smazat tuto vzpomínku?',id==='all'?'Uložené vzpomínky a poznatky se smažou. Chaty zůstanou.':'Smažou se i její dřívější verze.',[{id:'cancel',label:'Zrušit'},{id:'confirm',label:'Smazat',danger:true}])}
function confirmErase(){const id=state.eraseId;observations=observations.filter(r=>id!=='all'&&r.id!==id);saved=saved.filter(r=>id!=='all'&&r.id!==id);render('detail-heading');announce('Smazáno')}
function act(a){const [type,id]=a.split(':');if(type==='back')return back();if(type==='profile'){state.tab='observed';return go('overview')}if(type==='appearance')return go('appearance');if(type==='tab'){state.tab=id;state.view='overview';render('tab-'+id);return}if(type==='section'){state.section=id;state.open=(observations.find(r=>r.section===id&&r.personal===(state.scope==='personal'))||{}).id;return go('detail','detail-heading')}if(type==='all')return back();if(type==='expand'){state.open=state.open===id?null:id;render();document.querySelector(`[data-action="expand:${id}"]`)?.focus();return}if(type==='toggle'){state[id]=!state[id];render();document.querySelector(`[data-action="toggle:${id}"]`)?.focus();return}if(type==='source'){const r=observations.find(r=>r.id===id);modal(sourceText(r),r.source.at,[{id:'close',label:'Hotovo'}]);return}if(type==='delete')return askErase(id);if(type==='erase-menu'){modal('Správa paměti','',[{id:'cancel',label:'Zpět'},{id:'erase-all',label:'Smazat vše'}]);return}if(type==='correct'){const r=observations.find(r=>r.id===id)||saved.find(r=>r.id===id);state.editor={type:'memory',...r};return go('editor','edit-value')}if(type==='name'||type==='position'){state.editor={type};return go('editor','edit-value')}if(type==='theme'&&id){setTheme(id);render();document.querySelector(`[data-action="theme:${id}"]`)?.focus();return}if(type==='theme')return go('theme');if(type==='weather')return go('weather');if(type==='weather-context'){modal('Počasí','Volba zdroje je návrh. Tato ukázka polohu nezjišťuje.',[{id:'close',label:'Hotovo'}]);return}}
function bind(){document.querySelectorAll('[role=radio]').forEach(r=>r.addEventListener('keydown',e=>{const keys=['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();const ids=['system','light','dark'],i=ids.indexOf(state.theme),next=e.key==='Home'?0:e.key==='End'?2:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?2:1))%3;act('theme:'+ids[next])}));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));document.getElementById('scope')?.addEventListener('change',e=>{state.scope=e.target.value;render('scope')});document.getElementById('edit-form')?.addEventListener('submit',e=>{e.preventDefault();const value=document.getElementById('edit-value').value.trim();if(!value)return;const ed=state.editor;if(ed.type==='name')state.name=value;else if(ed.type==='position'){state.position=value;state.department=document.getElementById('department').value.trim()}else{observations=observations.filter(r=>r.id!==ed.id);saved=saved.filter(r=>r.id!==ed.id);saved.unshift({id:ed.id,content:value,trust:'user_assertion',source:'user_note'});history=[];state.tab='saved';state.view='overview';render(ed.id);requestAnimationFrame(()=>document.getElementById(ed.id)?.scrollIntoView({block:'nearest'}));announce('Uloženo do paměti');return}back();announce('Uloženo')})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){e.preventDefault();back()}});render();
